// Scene readouts double as the sole time, weather and season controls.
export function createSceneReadouts({title,icon}){
 const root=document.createElement('aside');root.id='scene-readouts';root.setAttribute('aria-label','Scene information');
 const widgets=document.createElement('div');widgets.className='scene-widgets';
 widgets.innerHTML='<button id="scene-clock-control" class="scene-clock" aria-label="Time of day"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="21"/><path d="M24 5v3m19 16h-3M24 43v-3M5 24h3"/><path class="hour-hand" d="M24 24V13"/><path class="minute-hand" d="M24 24V8"/></svg><span><strong class="clock-time"></strong><small class="clock-date"></small></span></button><div class="scene-weather"><button id="scene-weather-control" aria-label="Weather"><span class="weather-symbol"></span><strong class="weather-name"></strong></button><button id="scene-season-control" class="weather-season" aria-label="Season"></button></div>';
 root.append(title,widgets);document.body.append(root);let last='';
 return {setFamily(family){const ranch=family==='ranch';root.hidden=!ranch;if(ranch&&title.parentElement!==root)root.prepend(title);else if(!ranch&&title.parentElement===root)document.querySelector('header').prepend(title);},update({hour,day,weekday,weather,weatherSymbol,season}){const minute=Math.floor(hour*60)%1440,key=[minute,day,weather,season].join(':');if(key===last)return;last=key;const h=Math.floor(minute/60),m=minute%60;root.querySelector('.clock-time').textContent=`${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;root.querySelector('.clock-date').textContent=`${weekday} · Day ${day}`;root.querySelector('.hour-hand').setAttribute('transform',`rotate(${hour*30} 24 24)`);root.querySelector('.minute-hand').setAttribute('transform',`rotate(${m*6} 24 24)`);root.querySelector('.weather-symbol').innerHTML=icon(weatherSymbol);root.querySelector('.weather-name').textContent=weather;root.querySelector('.weather-season').textContent=season;}};
}
